    formats = list(requirement.get("formats") or ())
    if len(kinds) == 1:
        allowed = _KIND_FORMATS.get(kinds[0]) or set()
        if len(allowed) == 1 and not formats:
            formats = sorted(allowed)
    return {"kinds": kinds, "formats": formats}

